{
  "oneOf": [
    {
      "$ref": "#/components/schemas/AEInsurance.AEInsuranceQuoteResponsePendingProperties"
    },
    {
      "$ref": "#/components/schemas/AEInsurance.AEInsuranceQuoteResponseAvailableProperties"
    }
  ],
