    "propertyName": "QuoteStatus",
    "mapping": {
      "Pending": "#/components/schemas/AEInsurance.AEInsuranceQuoteResponsePendingProperties",
      "Available": "#/components/schemas/AEInsurance.AEInsuranceQuoteResponseAvailableProperties"
    }
  }
}

{
  "type": "object",
  "required": [
    "QuoteStatus",
    "QuoteId",
    "QuoteReference"
  ],
  "properties": {
    "QuoteStatus": {
      "type": "string",
      "enum": [
        "Pending"
      ],
      "description": "The current status of the quote"
    },
    "QuoteId": {
      "$ref": "#/components/schemas/AEInsurance.AEInsuranceQuoteIdType"
    },
    "QuoteReference": {
      "$ref": "#/components/schemas/AEInsurance.AEInsuranceQuoteReferenceType"
    },
    "PremiumTargetDateTime": {
      "type": "string",
      "format": "date-time",
      "description": "The target date and time at which the insurer will generate a quote premium. Maximum allowed time is 24 hours from quote resource creation."
    }
  }
}

{
  "type": "string",
  "description": "A unique identifier assigned to the generated insurance quote by the LFI"
}

{
  "type": "string",
  "description": "The unique quote reference number generated by the TPP for tracking the quote"
}

{
  "type": "object",
  "required": [
    "QuoteStatus",
    "QuoteId",
    "QuoteReference",
    "CreationDateTime",
    "ServiceRating",
    "PolicyIssuanceAllowed"
  ],
  "properties": {
    "QuoteStatus": {
      "type": "string",
      "enum": [
        "Available"
      ],
      "description": "The current status of the quote"
    },
    "QuoteId": {
      "$ref": "#/components/schemas/AEInsurance.AEInsuranceQuoteIdType"
    },
    "QuoteReference": {
      "$ref": "#/components/schemas/AEInsurance.AEInsuranceQuoteReferenceType"
    },
    "CreationDateTime": {
      "type": "string",
      "format": "date-time",
      "description": "The date and time at which the quote was created."
    },
    "ExpirationDateTime": {
      "type": "string",
      "format": "date-time",
      "description": "The expiration date of the quote, after which it is no longer valid.  If no date is provided the quote will be valid for up to 30 days as per the Standards."
    },
    "PlanName": {
      "type": "string",
      "minLength": 1,
      "maxLength": 140,
      "description": "The specific name of the insurance plan."
    },
    "LevelOfCover": {
      "type": "string",
      "minLength": 1,
      "maxLength": 140,
      "description": "The level of insurance Cover offered in the quote"
    },
    "Commission": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEInsurance.AEInsuranceCommission"
        }
      ],
      "description": "An object containing details of the commission amount that would be payable to the TPP if the User proceeded with the insurance application and purchased the policy based on the provided information"
    },
    "PolicyCover": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/AEInsurance.AEInsuranceQuotePolicyCover"
      },
      "minItems": 1,
      "description": "An array containing options for policy cover, which contain information about the cover and benefits included in the quoted policies."
    },
    "PolicyDocumentsUris": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/AEInsurance.AEInsuranceQuoteUri"
      },
      "minItems": 1,
      "description": "A list of URLs linking to policy-related documents, such as terms and conditions, policy wording, or product disclosures"
    },
    "AvailableAddOns": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "CoverName": {
            "type": "string",
            "minLength": 1,
            "maxLength": 70,
            "description": "Name of the insurance cover add-on"
          },
          "Description": {
            "type": "string",
            "minLength": 1,
            "maxLength": 140,
            "description": "Description of the insurance cover add-on"
          },
          "Amount": {
            "allOf": [
              {
                "$ref": "#/components/schemas/AEInsurance.AEActiveCurrencyAmount"
              }
            ],
            "description": "Premium value of the insurance cover add-on"
          },
          "CoverLimit": {
            "allOf": [
              {
                "$ref": "#/components/schemas/AEInsurance.AEActiveCurrencyAmount"
              }
            ],
            "description": "When applicable, the benefit coverage limit that could be paid if a claim was made."
          },
          "CoverInclusionAndExclusionDescriptions": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "minItems": 1,
            "description": "Included inclusions and exclusions for cover type."
          },
          "PolicyExcess": {
            "allOf": [
              {
                "$ref": "#/components/schemas/AEInsurance.AEActiveCurrencyAmount"
              }
            ],
            "description": "When applicable, the amount that would be deductible from any claim."
          }
        },
        "required": [
          "CoverName",
          "Description"
        ]
      },
      "minItems": 1,
      "description": "An object containing details of optional add-ons available for the quoted policy"
    },
    "RequiredDocuments": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/AEInsurance.AEInsuranceDocumentRequirement"
      },
      "minItems": 1,
      "description": "A list of documents required that must be provided by the User to the LFI to proceed with the policy purchase"
    },
    "DiscountOffers": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/AEInsurance.AEInsurancePremiumDiscountOffers"
      },
      "minItems": 1,
      "description": "An object containing details of any discounts or offers applied to the quote"
    },
    "ServiceRating": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEInsurance.AEInsuranceServiceRating"
        }
      ],
      "description": "An object containing ratings or reviews of the insurer's service quality"
    },
    "SpecialConditionsApplicable": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/AEInsurance.AEInsuranceSpecialConditions"
      },
      "description": "Provides special conditions or clauses applicable to the policy specified by the LFI, which must be displayed to the User if provided."
    },
    "PolicyIssuanceAllowed": {
      "type": "object",
      "properties": {
        "CustomerVerification": {
          "type": "boolean",
          "description": "Broker allowed to complete capture of customer verification information and documents for this quote."
        },
        "Payment": {
          "type": "boolean",
          "description": "Broker allowed to host payment checkout."
        },
        "PolicyDocuments": {
          "type": "boolean",
          "description": "Broker allowed to provide policy documents to customer."
        }
      },
      "required": [
        "CustomerVerification",
        "Payment",
        "PolicyDocuments"
      ],
      "description": "Broker requests to handle following steps of policy issuance process."
    },
    "Takaful": {
      "type": "boolean",
      "description": "Indicates whether the policy is Sharia compliant."
    },
    "AlternativeBrandName": {
      "type": "string",
      "description": "Provides and alternative brand name where the product is Sharia compliant"
    },
    "Premium": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEInsurance.AEInsurancePremiumProperties"
        }
      ],
      "minProperties": 1,
      "description": "An object containing details of the quoted insurance premium."
    }
  }
}

{
  "type": "object",
  "required": [
    "CommissionAmount",
    "CommissionPercentage"
  ],
  "properties": {
    "CommissionAmount": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEInsurance.AEActiveCurrencyAmount"
        }
      ],
      "description": "The total monetary value of the commission paid to the TPP if the User proceeds with the quote application and purchases the policy based on the quote information provided."
    },
    "CommissionPercentage": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEInsurance.AEInsurancePercentageValue"
        }
      ],
      "description": "The percentage of the policy premium allocated as commission to the TPP"
    },
    "PaymentMethod": {
      "type": "string",
      "enum": [
        "DirectToTPP",
        "ThroughAPIHub"
      ],
      "description": "The method to be used to pay the commission to the TPP if the User elects to proceed with the application and successfully purchases the policy."
    }
  }
}

{
  "type": "object",
  "required": [
    "Currency",
    "Amount"
  ],
  "properties": {
    "Currency": {
      "$ref": "#/components/schemas/AEInsurance.AEActiveOrHistoricCurrencyCode"
    },
    "Amount": {
      "$ref": "#/components/schemas/AEInsurance.AEActiveOrHistoricAmount"
    }
  },
  "description": "The Currency and Amount relating to the Payment, Refund or Request to Pay"
}

{
  "type": "string",
  "pattern": "^[A-Z]{3,3}$",
  "description": "A 3 character alphabetic code allocated to a currency under an international currency identification scheme, as described in the latest edition of the international standard ISO 4217 'Codes for the representation of currencies and funds'.",
  "example": "AED"
}

{
  "type": "string",
  "pattern": "^\\d{1,16}\\.\\d{2}$",
  "description": "A number of monetary units specified in an active currency where the unit of currency is explicit and compliant with ISO 4217.",
  "example": "100.00"
}

{
  "type": "number",
  "format": "decimal",
  "minimum": 0,
  "maximum": 100
}

{
  "type": "object",
  "required": [
    "CoverType",
    "Description",
    "CoverIncludedByDefaultIndicator"
  ],
  "properties": {
    "CoverId": {
      "type": "string",
      "description": "Insurers internal unique ID for specific cover"
    },
    "CoverType": {
      "type": "string",
      "description": "The category of Cover provided under the insurance policy"
    },
    "Description": {
      "type": "string",
      "description": "A description of the cover type"
    },
    "CoverIncludedByDefaultIndicator": {
      "type": "boolean",
      "description": "Indicates whether this Cover is included in the policy by default"
    },
    "CoverLimitAmount": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEInsurance.AEActiveCurrencyAmount"
        }
      ],
      "description": "Required if PolicyCoverIncluded is true (Yes) to provide confirmation of the maximum financial amount the insurer will cover for this specific Cover."
    },
    "PolicyFeatures": {
      "type": "string",
      "description": "The benefits or additional details related to the specific policy cover."
    },
    "PolicyExcess": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEInsurance.AEActiveCurrencyAmount"
        }
      ],
      "description": "Required if PolicyCoverIncluded is true (Yes) to confirm the deductible or out-of-pocket (excess) amount the policyholder must pay before the insurer covers the remaining claim."
    },
    "CoverInclusionAndExclusionDescriptions": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "minItems": 1,
      "description": "Included inclusions and exclusions for cover type."
    }
  }
}

{
  "type": "string",
  "format": "uri"
}

{
  "type": "string",
  "minLength": 1,
  "maxLength": 500
}

{
  "type": "object",
  "properties": {
    "Type": {
      "type": "string",
      "description": "The category or type of discount offer available"
    },
    "Name": {
      "type": "string",
      "description": "The name of the specific discount offer applied or available."
    },
    "Description": {
      "type": "string",
      "description": "A brief description of the discount offer, including key details and eligibility requirements."
    },
    "Criteria": {
      "type": "string",
      "description": "The conditions that must be met to qualify for the discount offer"
    },
    "OfferAmount": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEInsurance.AEActiveCurrencyAmount"
        }
      ],
      "description": "The total monetary value of the discount offer."
    },
    "DiscountPercentage": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEInsurance.AEInsurancePercentageValue"
        }
      ],
      "description": "The percentage reduction applied to the insurance premium as part of the discount."
    }
  }
}

{
  "type": "object",
  "required": [
    "FinancialStrength",
    "ClaimsServicePerformance",
    "CustomerServiceComplaintHandling",
    "PolicyDigitalConvenience"
  ],
  "properties": {
    "FinancialStrength": {
      "type": "object",
      "properties": {
        "SolvencyRatio": {
          "allOf": [
            {
              "$ref": "#/components/schemas/AEInsurance.AEInsuranceServiceRatingRateOrRatio"
            }
          ],
          "description": "The Solvency Capital Requirement (SCR) is a measure used to determine the minimum amount of capital that insurance companies must hold to ensure they can meet their obligations even under extreme financial stress."
        },
        "YearsInBusiness": {
          "type": "integer",
          "description": "The length of time the insurer LFI has been licensed in the UAE market to provide the type of insurance requested in the quote"
        }
      },
      "required": [
        "SolvencyRatio",
        "YearsInBusiness"
      ],
      "description": "Key indicators to assess the financial strength and stability of the insurer LFI in terms of their ability to meet obligations to policyholders."
    },
    "ClaimsServicePerformance": {
      "type": "object",
      "properties": {
        "AverageClaimSettlementTime": {
          "allOf": [
            {
              "$ref": "#/components/schemas/AEInsurance.AEInsuranceServiceRatingRateOrRatio"
            }
          ],
          "description": "Represents the average number of calendar days taken by the insurer to settle (pay) a claim, measured from the date the claim was filed, for the specific type of insurance coverage requested in this quote."
        },
        "ClaimSettlementRatio": {
          "allOf": [
            {
              "$ref": "#/components/schemas/AEInsurance.AEInsuranceServiceRatingPercentage"
            }
          ],
          "description": "Indicates the percentage of claims successfully paid by the insurer (LFI) out of the total number of claims filed for the type of insurance coverage requested in this quote."
        },
        "ClaimRejectionRate": {
          "allOf": [
            {
              "$ref": "#/components/schemas/AEInsurance.AEInsuranceServiceRatingPercentage"
            }
          ],
          "description": "Represents the percentage of claims that were rejected or denied by the insurer (LFI) relative to the total number of claims received for the type of insurance coverage requested in this quote."
        },
        "ClaimsPaymentCapacityRatio": {
          "allOf": [
            {
              "$ref": "#/components/schemas/AEInsurance.AEInsuranceServiceRatingRateOrRatio"
            }
          ],
          "description": "Indicates the insurer’s short-term ability to meet claims obligations using its liquid assets. The calculation is: Liquid assets divided by total claims payable."
        }
      },
      "required": [
        "AverageClaimSettlementTime",
        "ClaimSettlementRatio",
        "ClaimRejectionRate",
        "ClaimsPaymentCapacityRatio"
      ],
